(() => {
  "use strict";

  const IMAGE_DATA = {
    logo: { base64: "", width: 412, height: 420 },
    signature: { base64: "", width: 697, height: 320 },
    stamp: { base64: "", width: 500, height: 478 }
  };

  const A4_WIDTH = 595.28;
  const A4_HEIGHT = 841.89;
  const encoder = new TextEncoder();

  function bytesFromBase64(value){
    const binary=atob(value);
    const bytes=new Uint8Array(binary.length);
    for(let i=0;i<binary.length;i++) bytes[i]=binary.charCodeAt(i);
    return bytes;
  }

  function joinBytes(parts){
    const total=parts.reduce((sum,part)=>sum+part.length,0);
    const output=new Uint8Array(total);
    let offset=0;
    parts.forEach(part=>{output.set(part,offset);offset+=part.length;});
    return output;
  }

  function ascii(value){
    return String(value??"")
      .normalize("NFKD")
      .replace(/[\u0300-\u036f]/g,"")
      .replace(/[–—]/g,"-")
      .replace(/[‘’]/g,"'")
      .replace(/[“”]/g,'"')
      .replace(/×/g,"x")
      .replace(/•/g,"-")
      .replace(/…/g,"...")
      .replace(/[^\x20-\x7E]/g," ")
      .replace(/\s+/g," ")
      .trim();
  }

  function pdfEscape(value){
    return ascii(value).replace(/\\/g,"\\\\").replace(/\(/g,"\\(").replace(/\)/g,"\\)");
  }

  function rupiah(value){
    const number=Math.round(Number(value)||0);
    return "Rp " + number.toLocaleString("id-ID");
  }

  function dateId(value){
    if(!value) return "-";
    const parts=String(value).slice(0,10).split("-").map(Number);
    if(parts.length!==3 || !parts[0]) return ascii(value);
    const months=["Jan","Feb","Mar","Apr","Mei","Jun","Jul","Agu","Sep","Okt","Nov","Des"];
    return `${String(parts[2]).padStart(2,"0")} ${months[parts[1]-1]||""} ${parts[0]}`;
  }

  function textWidth(text,size,bold=false){
    return ascii(text).length*size*(bold?0.56:0.52);
  }

  function truncate(text,maxWidth,size,bold=false){
    let value=ascii(text);
    if(textWidth(value,size,bold)<=maxWidth) return value;
    while(value.length>2 && textWidth(value+"...",size,bold)>maxWidth) value=value.slice(0,-1);
    return value+"...";
  }

  function wrapText(text,maxWidth,size,bold=false,maxLines=3){
    const words=ascii(text).split(/\s+/).filter(Boolean);
    const lines=[];
    let line="";
    for(const word of words){
      const candidate=line?`${line} ${word}`:word;
      if(textWidth(candidate,size,bold)<=maxWidth){
        line=candidate;
      }else{
        if(line) lines.push(line);
        line=word;
        if(lines.length===maxLines-1) break;
      }
    }
    if(line && lines.length<maxLines) lines.push(line);
    if(words.length && lines.length===maxLines){
      const joined=lines.join(" ");
      if(joined.length<ascii(text).length) lines[maxLines-1]=truncate(lines[maxLines-1]+"...",maxWidth,size,bold);
    }
    return lines.length?lines:[""];
  }

  function buildContent(payload){
    const inv=payload.invoice||{};
    const settings=payload.settings||{};
    const items=[...(inv.invoice_items||[])].sort((a,b)=>(a.sort_order||0)-(b.sort_order||0));
    const commands=[];
    const navy=[0.059,0.204,0.259];
    const blue=[0.075,0.518,0.710];
    const ink=[0.090,0.184,0.227];
    const muted=[0.40,0.49,0.53];
    const line=[0.84,0.89,0.91];
    const panel=[0.973,0.984,0.988];
    const green=[0.176,0.60,0.36];

    const n=v=>Number(v).toFixed(2).replace(/\.00$/,"");
    const yFromTop=top=>A4_HEIGHT-top;
    const setFill=color=>commands.push(`${color.map(n).join(" ")} rg`);
    const setStroke=color=>commands.push(`${color.map(n).join(" ")} RG`);
    const rect=(x,top,w,h,fillColor=null,strokeColor=null,lineWidth=1)=>{
      if(fillColor) setFill(fillColor);
      if(strokeColor){setStroke(strokeColor);commands.push(`${n(lineWidth)} w`);}
      const op=fillColor&&strokeColor?"B":fillColor?"f":"S";
      commands.push(`${n(x)} ${n(A4_HEIGHT-top-h)} ${n(w)} ${n(h)} re ${op}`);
    };
    const lineTo=(x1,top1,x2,top2,color=line,width=1)=>{
      setStroke(color);commands.push(`${n(width)} w ${n(x1)} ${n(yFromTop(top1))} m ${n(x2)} ${n(yFromTop(top2))} l S`);
    };
    const drawText=(value,x,top,size=9,options={})=>{
      const bold=!!options.bold;
      const color=options.color||ink;
      const maxWidth=options.maxWidth||0;
      let text=ascii(value);
      if(maxWidth) text=truncate(text,maxWidth,size,bold);
      let tx=x;
      const width=textWidth(text,size,bold);
      if(options.align==="right") tx=x-width;
      if(options.align==="center") tx=x-width/2;
      setFill(color);
      commands.push(`BT /${bold?"F2":"F1"} ${n(size)} Tf 1 0 0 1 ${n(tx)} ${n(yFromTop(top))} Tm (${pdfEscape(text)}) Tj ET`);
    };
    const drawWrapped=(value,x,top,maxWidth,size=8,lineHeight=11,options={})=>{
      const lines=wrapText(value,maxWidth,size,!!options.bold,options.maxLines||3);
      lines.forEach((text,index)=>drawText(text,x,top+index*lineHeight,size,{...options,maxWidth}));
      return lines.length*lineHeight;
    };
    const drawImage=(name,x,top,w,h)=>{
      commands.push(`q ${n(w)} 0 0 ${n(h)} ${n(x)} ${n(A4_HEIGHT-top-h)} cm /${name} Do Q`);
    };

    rect(0,0,A4_WIDTH,8,navy);
    rect(430,0,A4_WIDTH-430,8,blue);

    drawImage("ImLogo",28,20,70,70);
    drawText(settings.store_name||"LORHIL AC",110,43,23,{bold:true,color:navy,maxWidth:235});
    drawText("SPESIALIS AIR CONDITIONER",110,62,10,{bold:true,color:blue,maxWidth:235});
    drawText(`WhatsApp: ${settings.phone||"081366752281"}`,110,82,8,{color:ink,maxWidth:235});
    drawText(`Alamat: ${settings.address||"LORHIL AC"}`,110,95,7.5,{color:muted,maxWidth:235});
    drawText("Layanan AC Baru, AC Second dan Jasa Servis",110,108,7.5,{color:muted,maxWidth:235});

    rect(358,20,209,108,navy);
    rect(358,20,5,108,blue);
    drawText("INVOICE",545,48,25,{bold:true,color:[1,1,1],align:"right"});
    drawText("NO.",380,72,7,{bold:true,color:[0.75,0.86,0.90]});
    drawText(inv.invoice_number||"-",545,72,9,{bold:true,color:[1,1,1],align:"right",maxWidth:150});
    drawText("TANGGAL",380,91,7,{bold:true,color:[0.75,0.86,0.90]});
    drawText(`${dateId(inv.work_date)} ${(inv.work_time||"").slice(0,5)}`,545,91,8,{bold:true,color:[1,1,1],align:"right",maxWidth:150});
    drawText("STATUS",380,111,7,{bold:true,color:[0.75,0.86,0.90]});
    rect(470,97,75,22,[0.87,0.96,0.90]);
    drawText(inv.status||"-",507.5,112,8,{bold:true,color:green,align:"center",maxWidth:68});

    rect(28,145,260,78,panel,line,0.8);
    rect(307,145,260,78,panel,line,0.8);
    drawText("RINCIAN KONTAK",43,168,9,{bold:true,color:navy});
    drawText(`WhatsApp: ${settings.phone||"081366752281"}`,43,188,8,{color:ink,maxWidth:225});
    drawWrapped(`Alamat: ${settings.address||"LORHIL AC"}`,43,204,225,7.5,10,{color:muted,maxLines:2});

    drawText("KEPADA",322,168,9,{bold:true,color:navy});
    drawText(inv.customer_name||"Pelanggan",322,188,12,{bold:true,color:ink,maxWidth:225});
    drawText(`WhatsApp: ${inv.customer_phone||"-"}`,322,205,8,{color:ink,maxWidth:225});
    drawText(`Alamat: ${inv.customer_address||"-"}`,322,219,7.3,{color:muted,maxWidth:225});

    const tableX=28, tableW=539, tableTop=240, headerH=27;
    const count=Math.max(1,items.length);
    const rowH=Math.max(17,Math.min(25,300/count));
    const fontSize=rowH<20?7:8;
    rect(tableX,tableTop,tableW,headerH,navy);
    drawText("NO.",48,258,7.5,{bold:true,color:[1,1,1],align:"center"});
    drawText("KETERANGAN",73,258,7.5,{bold:true,color:[1,1,1]});
    drawText("HARGA UNIT",390,258,7.5,{bold:true,color:[1,1,1],align:"right"});
    drawText("QTY",435,258,7.5,{bold:true,color:[1,1,1],align:"center"});
    drawText("TOTAL",548,258,7.5,{bold:true,color:[1,1,1],align:"right"});

    let rowTop=tableTop+headerH;
    const visibleItems=items.slice(0,17);
    visibleItems.forEach((item,index)=>{
      if(index%2===1) rect(tableX,rowTop,tableW,rowH,[0.985,0.99,0.992]);
      lineTo(tableX,rowTop+rowH,tableX+tableW,rowTop+rowH,line,0.6);
      drawText(String(index+1),48,rowTop+rowH*0.65,fontSize,{align:"center",color:ink});
      drawText(item.description||"-",73,rowTop+rowH*0.65,fontSize,{bold:true,color:ink,maxWidth:220});
      drawText(rupiah(item.unit_price),390,rowTop+rowH*0.65,fontSize,{align:"right",color:ink,maxWidth:85});
      drawText(String(item.quantity||0),435,rowTop+rowH*0.65,fontSize,{align:"center",color:ink});
      const lineTotal=Number(item.line_total ?? ((Number(item.quantity)||0)*(Number(item.unit_price)||0)))||0;
      drawText(rupiah(lineTotal),548,rowTop+rowH*0.65,fontSize,{align:"right",bold:true,color:blue,maxWidth:100});
      rowTop+=rowH;
    });
    if(items.length>visibleItems.length){
      drawText(`+ ${items.length-visibleItems.length} rincian lain`,73,rowTop+13,7,{color:muted});
      rowTop+=18;
    }
    rect(tableX,tableTop,tableW,rowTop-tableTop,null,line,0.8);

    const lowerTop=Math.min(590,Math.max(rowTop+18,455));
    rect(28,lowerTop,250,92,panel,line,0.8);
    drawText("METODE PEMBAYARAN",42,lowerTop+22,8.5,{bold:true,color:navy});
    drawWrapped(settings.payment_info||"Tunai / Transfer",42,lowerTop+42,220,7.5,10,{color:ink,maxLines:4});

    rect(291,lowerTop,276,142,[1,1,1],navy,0.9);
    rect(291,lowerTop,276,27,navy);
    drawText("RINGKASAN TOTAL",307,lowerTop+18,8.5,{bold:true,color:[1,1,1]});
    const totalRows=[
      ["Subtotal",inv.subtotal],
      ["Diskon",inv.discount],
      ["Dibayar",inv.paid],
      ["Sisa",inv.balance]
    ];
    totalRows.forEach((row,index)=>{
      const top=lowerTop+48+index*19;
      drawText(row[0],307,top,8,{color:muted});
      drawText(rupiah(row[1]),550,top,8,{bold:true,align:"right",color:ink,maxWidth:130});
    });
    rect(291,lowerTop+116,276,26,blue);
    drawText("TOTAL",307,lowerTop+134,10,{bold:true,color:[1,1,1]});
    drawText(rupiah(inv.total),550,lowerTop+134,11,{bold:true,align:"right",color:[1,1,1],maxWidth:160});

    const notesTop=lowerTop+106;
    rect(28,notesTop,250,80,[1,1,1],line,0.8);
    drawText("CATATAN",42,notesTop+22,8.5,{bold:true,color:navy});
    drawWrapped(inv.notes||settings.footer_note||"Terima kasih telah menggunakan layanan LORHIL AC.",42,notesTop+42,220,7.2,9,{color:ink,maxLines:4});

    const signTop=Math.max(lowerTop+205,690);
    drawText("Hormat kami,",65,signTop,8,{color:muted});
    drawImage("ImSignature",45,signTop+8,115,48);
    drawImage("ImStamp",145,signTop+5,65,62);
    drawText(settings.signer_name||"Hendri Nova Lismana",102,signTop+73,9,{bold:true,align:"center",color:ink,maxWidth:160});
    drawText(settings.signer_role||"Pemilik LORHIL AC",102,signTop+86,7.5,{align:"center",color:muted,maxWidth:160});

    rect(300,signTop,267,70,panel,line,0.8);
    drawText("TERIMA KASIH",433.5,signTop+28,17,{bold:true,align:"center",color:navy});
    drawText(settings.footer_note||"Terima kasih telah menggunakan layanan LORHIL AC.",433.5,signTop+48,7.5,{align:"center",color:muted,maxWidth:230});

    rect(0,818,A4_WIDTH,24,navy);
    drawText("Instagram: lorhillac",65,834,7.5,{color:[1,1,1]});
    drawText(`WhatsApp: ${settings.phone||"081366752281"}`,530,834,7.5,{color:[1,1,1],align:"right"});

    return commands.join("\n");
  }

  function createPdfBytes(payload){
    const contentBytes=encoder.encode(buildContent(payload));
    const images={
      7:{name:"ImLogo",...IMAGE_DATA.logo},
      8:{name:"ImSignature",...IMAGE_DATA.signature},
      9:{name:"ImStamp",...IMAGE_DATA.stamp}
    };
    const parts=[];
    const offsets=[0];
    let length=0;
    const add=part=>{
      const bytes=typeof part==="string"?encoder.encode(part):part;
      parts.push(bytes);length+=bytes.length;
    };
    const object=(number,body)=>{
      offsets[number]=length;
      add(`${number} 0 obj\n${body}\nendobj\n`);
    };
    const streamObject=(number,dictionary,streamBytes)=>{
      offsets[number]=length;
      add(`${number} 0 obj\n<< ${dictionary} /Length ${streamBytes.length} >>\nstream\n`);
      add(streamBytes);
      add("\nendstream\nendobj\n");
    };

    add("%PDF-1.4\n%LORHIL\n");
    object(1,"<< /Type /Catalog /Pages 2 0 R >>");
    object(2,"<< /Type /Pages /Kids [3 0 R] /Count 1 >>");
    object(3,`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${A4_WIDTH} ${A4_HEIGHT}] /Resources << /Font << /F1 5 0 R /F2 6 0 R >> /XObject << /ImLogo 7 0 R /ImSignature 8 0 R /ImStamp 9 0 R >> >> /Contents 4 0 R >>`);
    streamObject(4,"",contentBytes);
    object(5,"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>");
    object(6,"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>");

    Object.entries(images).forEach(([number,image])=>{
      const data=bytesFromBase64(image.base64);
      streamObject(Number(number),`/Type /XObject /Subtype /Image /Width ${image.width} /Height ${image.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode`,data);
    });

    const xrefOffset=length;
    add(`xref\n0 10\n0000000000 65535 f \n`);
    for(let i=1;i<=9;i++) add(`${String(offsets[i]).padStart(10,"0")} 00000 n \n`);
    add(`trailer\n<< /Size 10 /Root 1 0 R >>\nstartxref\n${xrefOffset}\n%%EOF\n`);
    return joinBytes(parts);
  }

  function createPdfBlob(payload){
    return new Blob([createPdfBytes(payload)],{type:"application/pdf"});
  }

  function filename(payload){
    return String(payload.filename||"nota-lorhil-ac.pdf").replace(/[^a-zA-Z0-9._-]+/g,"-");
  }

  function triggerDownload(blob,name){
    const url=URL.createObjectURL(blob);
    const isiOS=/iPad|iPhone|iPod/.test(navigator.userAgent);
    if(isiOS){
      const opened=window.open(url,"_blank");
      if(!opened) window.location.href=url;
    }else{
      const link=document.createElement("a");
      link.href=url;
      link.download=name;
      link.rel="noopener";
      link.style.display="none";
      document.body.appendChild(link);
      link.click();
      link.remove();
    }
    setTimeout(()=>URL.revokeObjectURL(url),180000);
  }

  function whatsappUrl(payload){
    const phone=String(payload.phone||"").replace(/\D/g,"");
    const message=String(payload.message||"");
    return `https://wa.me/${phone}?text=${encodeURIComponent(message)}`;
  }

  function showStatus(message){
    let box=document.getElementById("lorhilInvoiceStatus");
    if(!box){
      box=document.createElement("div");
      box.id="lorhilInvoiceStatus";
      box.style.cssText="position:fixed;left:50%;bottom:24px;transform:translateX(-50%);z-index:100000;background:#0f3442;color:#fff;padding:12px 16px;border-radius:10px;box-shadow:0 8px 24px rgba(0,0,0,.25);font:600 14px Arial;max-width:90%;text-align:center";
      document.body.appendChild(box);
    }
    box.textContent=message;
    box.style.display="block";
    clearTimeout(showStatus.timer);
    showStatus.timer=setTimeout(()=>{box.style.display="none";},3500);
  }

  function downloadPdf(payload){
    try{
      showStatus("Membuat PDF...");
      const blob=createPdfBlob(payload);
      triggerDownload(blob,filename(payload));
      showStatus("PDF berhasil dibuat. Periksa folder Download.");
      return true;
    }catch(error){
      console.error("Gagal membuat PDF",error);
      alert("PDF belum berhasil dibuat: "+(error?.message||error));
      return false;
    }
  }

  function downloadPdfAndOpenWhatsApp(payload){
    const phone=String(payload.phone||"").replace(/\D/g,"");
    if(phone.length<10){
      alert("Nomor WhatsApp pelanggan pada nota belum valid.");
      return false;
    }
    try{
      showStatus("Membuat dan mengunduh PDF...");
      const blob=createPdfBlob(payload);
      triggerDownload(blob,filename(payload));
      showStatus("PDF diunduh. Membuka WhatsApp pelanggan...");
      setTimeout(()=>{window.location.href=whatsappUrl(payload);},700);
      return true;
    }catch(error){
      console.error("Gagal mengunduh PDF dan membuka WhatsApp",error);
      alert("Proses belum berhasil: "+(error?.message||error));
      return false;
    }
  }

  function htmlEscape(value){
    return String(value??"").replace(/[&<>"']/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[char]));
  }

  function imageDataUri(image){
    return `data:image/jpeg;base64,${image.base64}`;
  }

  function buildPrintHtml(payload){
    const inv=payload.invoice||{};
    const s=payload.settings||{};
    const items=[...(inv.invoice_items||[])].sort((a,b)=>(a.sort_order||0)-(b.sort_order||0));
    return `<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>
      @page{size:A4;margin:0}*{box-sizing:border-box}html,body{margin:0;background:#eef3f5;font-family:Arial,sans-serif;color:#172f3a;-webkit-print-color-adjust:exact;print-color-adjust:exact}.sheet{width:210mm;min-height:297mm;margin:0 auto;background:#fff;position:relative;padding-bottom:18mm}.top{height:3mm;background:linear-gradient(90deg,#0f3442 0 72%,#1384b5 72%)}.header{display:grid;grid-template-columns:1fr 78mm;gap:7mm;padding:9mm 10mm 6mm}.brand{display:grid;grid-template-columns:34mm 1fr;gap:4mm;align-items:center}.brand img{width:32mm;height:32mm;object-fit:contain}.brand h1{margin:0;color:#0f3442;font-size:25pt}.brand b{color:#1384b5;font-size:9pt}.contact{margin-top:4mm;font-size:7.5pt;line-height:1.55}.invbox{background:#0f3442;color:#fff;padding:7mm 6mm;border-left:2mm solid #1384b5}.invbox h2{font-size:27pt;text-align:right;margin:0 0 5mm}.meta{display:grid;grid-template-columns:22mm 1fr;gap:2mm;font-size:7.5pt}.meta strong{text-align:right}.content{padding:0 9mm}.cards{display:grid;grid-template-columns:1fr 1fr;gap:4mm}.card{border:1px solid #d8e4e9;border-radius:3mm;padding:4mm;background:#f8fbfc;min-height:30mm}.card h3{margin:0 0 3mm;color:#0f3442;font-size:9pt}.card p{margin:1.5mm 0;font-size:7.5pt}.name{font-size:12pt!important;font-weight:700}.table{margin-top:4mm;border:1px solid #d8e4e9;border-radius:2mm;overflow:hidden}table{width:100%;border-collapse:collapse}th{background:#0f3442;color:#fff;font-size:7.5pt;padding:3mm;text-align:left}td{padding:3mm;border-bottom:1px solid #e5edf0;font-size:7.5pt}th:nth-child(1),td:nth-child(1),th:nth-child(4),td:nth-child(4){text-align:center}th:nth-child(3),td:nth-child(3),th:nth-child(5),td:nth-child(5){text-align:right}.bottom{display:grid;grid-template-columns:1fr 1.1fr;gap:4mm;margin-top:4mm}.notes{border:1px solid #d8e4e9;border-radius:2mm;padding:4mm;min-height:35mm;font-size:7.5pt;white-space:pre-wrap}.totals{border:1px solid #0f3442;border-radius:2mm;overflow:hidden}.totals h3{margin:0;background:#0f3442;color:#fff;padding:3mm;font-size:8.5pt}.row{display:flex;justify-content:space-between;padding:2.2mm 4mm;font-size:8pt}.grand{background:#1384b5;color:#fff;font-size:10pt;font-weight:700}.sign{display:grid;grid-template-columns:1fr 1fr;gap:6mm;align-items:center;margin-top:8mm}.signbox{text-align:center;position:relative;min-height:39mm}.sig{width:50mm;height:20mm;object-fit:contain}.stamp{position:absolute;width:27mm;height:27mm;object-fit:contain;left:55%;top:2mm}.thanks{border:1px solid #d8e4e9;background:#f8fbfc;border-radius:3mm;text-align:center;padding:8mm}.thanks strong{display:block;color:#0f3442;font-size:18pt}.footer{position:absolute;bottom:0;left:0;right:0;height:13mm;background:#0f3442;color:#fff;display:flex;justify-content:space-between;align-items:center;padding:0 10mm;font-size:7.5pt}@media print{html,body{background:#fff}.sheet{margin:0}}
    </style></head><body><article class="sheet"><div class="top"></div><header class="header"><section class="brand"><img src="${imageDataUri(IMAGE_DATA.logo)}"><div><h1>${htmlEscape(s.store_name||"LORHIL AC")}</h1><b>SPESIALIS AIR CONDITIONER</b><div class="contact">WhatsApp: ${htmlEscape(s.phone||"081366752281")}<br>Alamat: ${htmlEscape(s.address||"LORHIL AC")}<br>Layanan AC Baru, AC Second dan Jasa Servis</div></div></section><section class="invbox"><h2>INVOICE</h2><div class="meta"><span>NO.</span><strong>${htmlEscape(inv.invoice_number||"-")}</strong><span>TANGGAL</span><strong>${htmlEscape(dateId(inv.work_date))} ${htmlEscape((inv.work_time||"").slice(0,5))}</strong><span>STATUS</span><strong>${htmlEscape(inv.status||"-")}</strong></div></section></header><main class="content"><section class="cards"><div class="card"><h3>RINCIAN KONTAK</h3><p>WhatsApp: ${htmlEscape(s.phone||"081366752281")}</p><p>Alamat: ${htmlEscape(s.address||"LORHIL AC")}</p></div><div class="card"><h3>KEPADA</h3><p class="name">${htmlEscape(inv.customer_name||"Pelanggan")}</p><p>WhatsApp: ${htmlEscape(inv.customer_phone||"-")}</p><p>Alamat: ${htmlEscape(inv.customer_address||"-")}</p></div></section><section class="table"><table><thead><tr><th>No.</th><th>Keterangan</th><th>Harga Unit</th><th>Qty</th><th>Total</th></tr></thead><tbody>${items.map((item,index)=>`<tr><td>${index+1}</td><td>${htmlEscape(item.description||"-")}</td><td>${htmlEscape(rupiah(item.unit_price))}</td><td>${htmlEscape(item.quantity||0)}</td><td><strong>${htmlEscape(rupiah(item.line_total ?? ((Number(item.quantity)||0)*(Number(item.unit_price)||0))))}</strong></td></tr>`).join("")}</tbody></table></section><section class="bottom"><div><div class="notes"><strong>METODE PEMBAYARAN</strong><br>${htmlEscape(s.payment_info||"Tunai / Transfer")}</div><div class="notes" style="margin-top:4mm"><strong>CATATAN</strong><br>${htmlEscape(inv.notes||s.footer_note||"Terima kasih telah menggunakan layanan LORHIL AC.")}</div></div><div class="totals"><h3>RINGKASAN TOTAL</h3><div class="row"><span>Subtotal</span><strong>${htmlEscape(rupiah(inv.subtotal))}</strong></div><div class="row"><span>Diskon</span><strong>${htmlEscape(rupiah(inv.discount))}</strong></div><div class="row"><span>Dibayar</span><strong>${htmlEscape(rupiah(inv.paid))}</strong></div><div class="row"><span>Sisa</span><strong>${htmlEscape(rupiah(inv.balance))}</strong></div><div class="row grand"><span>Total</span><strong>${htmlEscape(rupiah(inv.total))}</strong></div></div></section><section class="sign"><div class="signbox">Hormat kami,<br><img class="sig" src="${imageDataUri(IMAGE_DATA.signature)}"><img class="stamp" src="${imageDataUri(IMAGE_DATA.stamp)}"><br><strong>${htmlEscape(s.signer_name||"Hendri Nova Lismana")}</strong><br><small>${htmlEscape(s.signer_role||"Pemilik LORHIL AC")}</small></div><div class="thanks"><strong>TERIMA KASIH</strong><span>${htmlEscape(s.footer_note||"Terima kasih telah menggunakan layanan LORHIL AC.")}</span></div></section></main><footer class="footer"><span>Instagram: lorhillac</span><span>WhatsApp: ${htmlEscape(s.phone||"081366752281")}</span></footer></article></body></html>`;
  }

  function closePrintPreview(){
    document.getElementById("lorhilPrintOverlay")?.remove();
  }

  function openPrintPreview(payload){
    closePrintPreview();
    const overlay=document.createElement("div");
    overlay.id="lorhilPrintOverlay";
    overlay.style.cssText="position:fixed;inset:0;z-index:99999;background:#dfe8ec;display:flex;flex-direction:column";
    const bar=document.createElement("div");
    bar.style.cssText="display:flex;gap:8px;flex-wrap:wrap;padding:10px;background:#fff;box-shadow:0 2px 10px rgba(0,0,0,.15);z-index:2";
    const button=(label,style,handler)=>{
      const btn=document.createElement("button");
      btn.type="button";btn.textContent=label;btn.style.cssText=`border:0;border-radius:9px;padding:11px 13px;color:#fff;font-weight:700;background:${style};cursor:pointer`;
      btn.addEventListener("click",handler);return btn;
    };
    const frame=document.createElement("iframe");
    frame.title="Preview Nota";
    frame.style.cssText="flex:1;width:100%;border:0;background:#eef3f5";
    frame.srcdoc=buildPrintHtml(payload);
    bar.appendChild(button("Cetak Sekarang","#0f3442",()=>{
      try{frame.contentWindow.focus();frame.contentWindow.print();}
      catch(error){console.error(error);alert("Dialog cetak tidak dapat dibuka. Gunakan tombol Download PDF.");}
    }));
    bar.appendChild(button("Download PDF","#1384b5",()=>downloadPdf(payload)));
    bar.appendChild(button("Download PDF & Buka WhatsApp","#1f8f5f",()=>downloadPdfAndOpenWhatsApp(payload)));
    bar.appendChild(button("Tutup","#6b7f88",closePrintPreview));
    overlay.appendChild(bar);overlay.appendChild(frame);document.body.appendChild(overlay);
    document.body.style.overflow="hidden";
    const observer=new MutationObserver(()=>{
      if(!document.body.contains(overlay)){document.body.style.overflow="";observer.disconnect();}
    });
    observer.observe(document.body,{childList:true});
    return true;
  }

  window.LorhilInvoiceEngine={
    createPdfBytes,
    createPdfBlob,
    downloadPdf,
    downloadPdfAndOpenWhatsApp,
    openPrintPreview,
    closePrintPreview,
    buildPrintHtml
  };
})();
